    private static readonly IReadOnlyList<Trade> Core =
    [
        new("trade-electricity", "⚡", "sun",
            Txt.Of("Electricity at home|Electricidad doméstica|L'électricité à la maison|Electricitat domèstica"),
            Txt.Of("How a home installation works: circuits, voltage and current, consumption, protections and safety.|Cómo funciona la instalación de una casa: circuitos, tensión y corriente, consumo, protecciones y seguridad.|Comment fonctionne une installation domestique : circuits, tension et courant, consommation, protections et sécurité.|Com funciona la instal·lació d'una casa: circuits, tensió i corrent, consum, proteccions i seguretat."),
            Txt.Of("Theory only. Never work on a live installation: real installations must be done by an authorised electrician.|Solo teoría. Nunca trabajes en una instalación con tensión: las instalaciones reales las hace un electricista autorizado.|Théorie uniquement. Ne travaille jamais sur une installation sous tension : les vraies installations sont faites par un électricien habilité.|Només teoria. No treballis mai en una instal·lació amb tensió: les instal·lacions reals les fa un electricista autoritzat."),
            [
                C("circuit", "The electric circuit|El circuito eléctrico|Le circuit électrique|El circuit elèctric", "Current only flows through a closed path from the source, through the device and back; a switch opens or closes that path.|La corriente solo circula por un camino cerrado desde la fuente, por el aparato y de vuelta; un interruptor abre o cierra ese camino.|Le courant ne circule que dans un chemin fermé, de la source à l'appareil et retour ; un interrupteur ouvre ou ferme ce chemin.|El corrent només circula per un camí tancat des de la font, per l'aparell i de tornada; un interruptor obre o tanca aquest camí.", Area.Physics, "Physics: electric current|Física: la corriente eléctrica|Physique : le courant électrique|Física: el corrent elèctric"),
                C("ohm", "Voltage, current and resistance|Tensión, corriente y resistencia|Tension, courant et résistance|Tensió, corrent i resistència", "Voltage pushes, current is what flows, resistance opposes it: V = I × R. Sockets in Europe give about 230 V.|La tensión empuja, la corriente es lo que circula y la resistencia se opone: V = I × R. Los enchufes en Europa dan unos 230 V.|La tension pousse, le courant est ce qui circule, la résistance s'y oppose : U = R × I. Les prises en Europe donnent environ 230 V.|La tensió empeny, el corrent és el que circula i la resistència s'hi oposa: V = I × R. Els endolls a Europa donen uns 230 V.", Area.Physics, "Physics: Ohm's law|Física: la ley de Ohm|Physique : la loi d'Ohm|Física: la llei d'Ohm", "circuit"),
                C("power", "Power and consumption|Potencia y consumo|Puissance et consommation|Potència i consum", "Power is P = V × I, in watts. The energy you pay for is power × time, in kilowatt-hours (kWh).|La potencia es P = V × I, en vatios. La energía que pagas es potencia × tiempo, en kilovatios hora (kWh).|La puissance est P = U × I, en watts. L'énergie que tu paies est puissance × temps, en kilowattheures (kWh).|La potència és P = V × I, en watts. L'energia que pagues és potència × temps, en quilowatts hora (kWh).", Area.Physics, "Physics: energy and power|Física: energía y potencia|Physique : énergie et puissance|Física: energia i potència", "ohm"),
                C("protection", "Protections: breaker and RCD|Protecciones: magnetotérmico y diferencial|Protections : disjoncteur et différentiel|Proteccions: magnetotèrmic i diferencial", "The circuit breaker cuts on overloads and short circuits (it protects the wires); the residual current device (RCD) cuts when current leaks, usually from 30 mA (it protects people).|El magnetotérmico corta con sobrecargas y cortocircuitos (protege los cables); el diferencial corta cuando la corriente se fuga, normalmente desde 30 mA (protege a las personas).|Le disjoncteur coupe en cas de surcharge et de court-circuit (il protège les fils) ; le différentiel coupe quand le courant fuit, en général dès 30 mA (il protège les personnes).|El magnetotèrmic talla amb sobrecàrregues i curtcircuits (protegeix els cables); el diferencial talla quan el corrent es fuga, normalment des de 30 mA (protegeix les persones).", Area.Biology, "Biology: the effects of current on the body|Biología: los efectos de la corriente en el cuerpo|Biologie : les effets du courant sur le corps|Biologia: els efectes del corrent en el cos", "power"),
                C("safety", "Safety: working without voltage|Seguridad: trabajar sin tensión|Sécurité : travailler hors tension|Seguretat: treballar sense tensió", "Before touching anything: switch off at the panel, check that there is no voltage with a tester, dry hands. Green-and-yellow is the earth wire.|Antes de tocar nada: cortar en el cuadro, comprobar con un comprobador que no hay tensión, manos secas. El cable verde y amarillo es la toma de tierra.|Avant de toucher quoi que ce soit : couper au tableau, vérifier l'absence de tension avec un testeur, mains sèches. Le fil vert et jaune est la terre.|Abans de tocar res: tallar al quadre, comprovar amb un comprovador que no hi ha tensió, mans seques. El cable verd i groc és la presa de terra.", Area.Biology, "Biology: why the body conducts electricity|Biología: por qué el cuerpo conduce la electricidad|Biologie : pourquoi le corps conduit l'électricité|Biologia: per què el cos condueix l'electricitat", "protection"),
            ],
            [
                Q("circuit", 1, "For a bulb to light up, the circuit must be…|Para que una bombilla se encienda, el circuito debe estar…|Pour qu'une ampoule s'allume, le circuit doit être…|Perquè una bombeta s'encengui, el circuit ha d'estar…", "closed|cerrado|fermé|tancat", "Current needs a complete loop to flow.|La corriente necesita un camino completo para circular.|Le courant a besoin d'une boucle complète pour circuler.|El corrent necessita un camí complet per circular.", "open|abierto|ouvert|obert", "connected with only one wire|conectado con un solo cable|branché avec un seul fil|connectat amb un sol cable", "without a source|sin fuente|sans source|sense font"),
                Q("circuit", 2, "What does a switch do?|¿Qué hace un interruptor?|Que fait un interrupteur ?|Què fa un interruptor?", "It opens or closes the circuit|Abre o cierra el circuito|Il ouvre ou ferme le circuit|Obre o tanca el circuit", "Off = open circuit, no current; on = closed circuit.|Apagado = circuito abierto, sin corriente; encendido = circuito cerrado.|Éteint = circuit ouvert, pas de courant ; allumé = circuit fermé.|Apagat = circuit obert, sense corrent; encès = circuit tancat.", "It produces electricity|Produce electricidad|Il produit de l'électricité|Produeix electricitat", "It raises the voltage|Aumenta la tensión|Il augmente la tension|Augmenta la tensió", "It stores energy|Guarda energía|Il stocke de l'énergie|Guarda energia"),
                Q("circuit", 3, "Which material is a good conductor, used inside cables?|¿Qué material es buen conductor y se usa dentro de los cables?|Quel matériau est un bon conducteur, utilisé dans les câbles ?|Quin material és bon conductor i es fa servir dins dels cables?", "Copper|El cobre|Le cuivre|El coure", "Metals like copper let electrons move easily; plastic covers them because it insulates.|Los metales como el cobre dejan moverse a los electrones; el plástico los recubre porque aísla.|Les métaux comme le cuivre laissent circuler les électrons ; le plastique les entoure car il isole.|Els metalls com el coure deixen moure els electrons; el plàstic els recobreix perquè aïlla.", "Plastic|El plástico|Le plastique|El plàstic", "Rubber|La goma|Le caoutchouc|La goma", "Dry wood|La madera seca|Le bois sec|La fusta seca"),
                Q("ohm", 1, "What is the voltage of a socket at home in Europe?|¿Qué tensión tiene un enchufe de casa en Europa?|Quelle est la tension d'une prise à la maison en Europe ?|Quina tensió té un endoll de casa a Europa?", "About 230 V|Unos 230 V|Environ 230 V|Uns 230 V", "The European standard is 230 V at 50 Hz.|El estándar europeo es 230 V a 50 Hz.|La norme européenne est 230 V à 50 Hz.|L'estàndard europeu és 230 V a 50 Hz.", "12 V", "1000 V", "50 V"),
                Q("ohm", 2, "If the resistance increases and the voltage stays the same, the current…|Si la resistencia aumenta y la tensión es la misma, la corriente…|Si la résistance augmente et que la tension reste la même, le courant…|Si la resistència augmenta i la tensió és la mateixa, el corrent…", "decreases|disminuye|diminue|disminueix", "I = V ÷ R: dividing by a bigger number gives less current.|I = V ÷ R: dividir por un número mayor da menos corriente.|I = U ÷ R : diviser par un plus grand nombre donne moins de courant.|I = V ÷ R: dividir per un nombre més gran dona menys corrent.", "increases|aumenta|augmente|augmenta", "stays the same|no cambia|ne change pas|no canvia", "doubles|se duplica|double|es duplica"),
                Q("ohm", 3, "A 2300 W appliance on 230 V draws a current of…|Un aparato de 2300 W a 230 V consume una corriente de…|Un appareil de 2300 W sous 230 V consomme un courant de…|Un aparell de 2300 W a 230 V consumeix un corrent de…", "10 A", "I = P ÷ V = 2300 ÷ 230 = 10 A.|I = P ÷ V = 2300 ÷ 230 = 10 A.|I = P ÷ U = 2300 ÷ 230 = 10 A.|I = P ÷ V = 2300 ÷ 230 = 10 A.", "0.1 A|0,1 A|0,1 A|0,1 A", "100 A", "2300 A"),
                Q("power", 1, "Which unit measures the energy on the electricity bill?|¿Qué unidad mide la energía de la factura de la luz?|Quelle unité mesure l'énergie sur la facture d'électricité ?|Quina unitat mesura l'energia de la factura de la llum?", "The kilowatt-hour (kWh)|El kilovatio hora (kWh)|Le kilowattheure (kWh)|El quilowatt hora (kWh)", "Energy = power × time, so kW × h.|Energía = potencia × tiempo, así que kW × h.|Énergie = puissance × temps, donc kW × h.|Energia = potència × temps, per tant kW × h.", "The volt (V)|El voltio (V)|Le volt (V)|El volt (V)", "The ampere (A)|El amperio (A)|L'ampère (A)|L'ampere (A)", "The ohm (Ω)|El ohmio (Ω)|L'ohm (Ω)|L'ohm (Ω)"),
                Q("power", 2, "A 2 kW oven working for 3 hours uses…|Un horno de 2 kW funcionando 3 horas consume…|Un four de 2 kW qui fonctionne 3 heures consomme…|Un forn de 2 kW funcionant 3 hores consumeix…", "6 kWh", "2 kW × 3 h = 6 kWh.|2 kW × 3 h = 6 kWh.|2 kW × 3 h = 6 kWh.|2 kW × 3 h = 6 kWh.", "5 kWh", "0.66 kWh|0,66 kWh|0,66 kWh|0,66 kWh", "2 kWh"),
                Q("power", 3, "A 10 W LED bulb replaces a 60 W bulb giving the same light. How much power does it save?|Una bombilla LED de 10 W sustituye a una de 60 W con la misma luz. ¿Cuánta potencia ahorra?|Une ampoule LED de 10 W remplace une ampoule de 60 W qui éclaire autant. Combien de puissance économise-t-elle ?|Una bombeta LED de 10 W substitueix una de 60 W amb la mateixa llum. Quanta potència estalvia?", "50 W", "60 − 10 = 50 W less, every hour it is on.|60 − 10 = 50 W menos cada hora que está encendida.|60 − 10 = 50 W de moins, à chaque heure d'allumage.|60 − 10 = 50 W menys cada hora que està encesa.", "6 W", "70 W", "Nothing|Nada|Rien|Res"),
                Q("protection", 1, "Which device protects people by detecting a current leak?|¿Qué dispositivo protege a las personas detectando una fuga de corriente?|Quel appareil protège les personnes en détectant une fuite de courant ?|Quin dispositiu protegeix les persones detectant una fuga de corrent?", "The residual current device (RCD)|El interruptor diferencial|Le disjoncteur différentiel|L'interruptor diferencial", "It compares the current that goes and comes back; if some is missing, it is leaking (maybe through a person) and it cuts.|Compara la corriente que va y la que vuelve; si falta algo, se está fugando (quizá por una persona) y corta.|Il compare le courant qui part et celui qui revient ; s'il en manque, il fuit (peut-être par une personne) et il coupe.|Compara el corrent que va i el que torna; si en falta, s'està fugint (potser per una persona) i talla.", "The circuit breaker|El magnetotérmico|Le disjoncteur magnétothermique|El magnetotèrmic", "The meter|El contador|Le compteur|El comptador", "The socket|El enchufe|La prise|L'endoll"),
                Q("protection", 2, "The circuit breaker trips when there is…|El magnetotérmico salta cuando hay…|Le disjoncteur se déclenche quand il y a…|El magnetotèrmic salta quan hi ha…", "an overload or a short circuit|una sobrecarga o un cortocircuito|une surcharge ou un court-circuit|una sobrecàrrega o un curtcircuit", "Too much current heats the wires; the breaker cuts before they get dangerous.|Demasiada corriente calienta los cables; el magnetotérmico corta antes de que sea peligroso.|Trop de courant chauffe les fils ; le disjoncteur coupe avant que ce soit dangereux.|Massa corrent escalfa els cables; el magnetotèrmic talla abans que sigui perillós.", "little light|poca luz|peu de lumière|poca llum", "a high bill|una factura alta|une facture élevée|una factura alta", "a cold day|un día frío|un jour froid|un dia fred"),
                Q("protection", 3, "What is the usual sensitivity of a home RCD?|¿Cuál es la sensibilidad habitual de un diferencial doméstico?|Quelle est la sensibilité habituelle d'un différentiel domestique ?|Quina és la sensibilitat habitual d'un diferencial domèstic?", "30 mA", "30 milliamperes: a leak that small is cut quickly to protect people.|30 miliamperios: una fuga tan pequeña se corta rápido para proteger a las personas.|30 milliampères : une fuite si petite est coupée vite pour protéger les personnes.|30 mil·liamperes: una fuga tan petita es talla ràpid per protegir les persones.", "30 A", "300 V", "3 W"),
                Q("safety", 1, "Before changing a socket, the first thing is to…|Antes de cambiar un enchufe, lo primero es…|Avant de changer une prise, la première chose est de…|Abans de canviar un endoll, el primer és…", "switch off at the panel and check there is no voltage|cortar en el cuadro y comprobar que no hay tensión|couper au tableau et vérifier l'absence de tension|tallar al quadre i comprovar que no hi ha tensió", "Switching off the light is not enough: the socket may be on another circuit.|Apagar la luz no basta: el enchufe puede estar en otro circuito.|Éteindre la lumière ne suffit pas : la prise peut être sur un autre circuit.|Apagar el llum no n'hi ha prou: l'endoll pot ser en un altre circuit.", "switch off only the light|apagar solo la luz|éteindre seulement la lumière|apagar només el llum", "wear wool gloves|ponerse guantes de lana|mettre des gants en laine|posar-se guants de llana", "do it fast|hacerlo rápido|le faire vite|fer-ho ràpid"),
                Q("safety", 2, "Why is it dangerous to touch appliances with wet hands?|¿Por qué es peligroso tocar aparatos con las manos mojadas?|Pourquoi est-il dangereux de toucher des appareils avec les mains mouillées ?|Per què és perillós tocar aparells amb les mans mullades?", "Wet skin lets current through much more easily|La piel mojada deja pasar la corriente mucho más fácilmente|La peau mouillée laisse passer le courant beaucoup plus facilement|La pell mullada deixa passar el corrent molt més fàcilment", "Water with salts lowers the resistance of the skin, so more current can cross the body.|El agua con sales baja la resistencia de la piel y puede pasar más corriente por el cuerpo.|L'eau avec des sels baisse la résistance de la peau, et plus de courant peut traverser le corps.|L'aigua amb sals abaixa la resistència de la pell i pot passar més corrent pel cos.", "Water produces electricity|El agua produce electricidad|L'eau produit de l'électricité|L'aigua produeix electricitat", "Water raises the voltage|El agua sube la tensión|L'eau augmente la tension|L'aigua puja la tensió", "It is not dangerous|No es peligroso|Ce n'est pas dangereux|No és perillós"),
                Q("safety", 3, "In a European installation, the green-and-yellow wire is…|En una instalación europea, el cable verde y amarillo es…|Dans une installation européenne, le fil vert et jaune est…|En una instal·lació europea, el cable verd i groc és…", "the earth|la toma de tierra|la terre|la presa de terra", "Earth takes leaks to the ground; the blue wire is neutral and brown, black or grey are phase.|La tierra lleva las fugas al suelo; el azul es el neutro y el marrón, negro o gris son fase.|La terre envoie les fuites dans le sol ; le bleu est le neutre et le marron, noir ou gris sont la phase.|La terra porta les fugues al terra; el blau és el neutre i el marró, negre o gris són fase.", "the phase|la fase|la phase|la fase", "the neutral|el neutro|le neutre|el neutre", "the switch wire|el del interruptor|le fil de l'interrupteur|el de l'interruptor"),
            ]),
        new("trade-garden", "🌱", "mint",
            Txt.Of("Vegetable garden and gardening|Huerto y jardín|Potager et jardinage|Hort i jardí"),
            Txt.Of("Grow plants, vegetables, flowers and trees: what plants need, soil and compost, sowing, watering, pollination and pruning.|Cultiva plantas, hortalizas, flores y árboles: lo que necesita una planta, el suelo y el compost, la siembra, el riego, la polinización y la poda.|Cultiver plantes, légumes, fleurs et arbres : les besoins d'une plante, le sol et le compost, les semis, l'arrosage, la pollinisation et la taille.|Conrea plantes, hortalisses, flors i arbres: el que necessita una planta, el sòl i el compost, la sembra, el reg, la pol·linització i la poda."),
            null,
            [
                C("needs", "What a plant needs|Lo que necesita una planta|Les besoins d'une plante|El que necessita una planta", "Light, water, air (CO₂), nutrients and the right temperature. With light, the leaves turn water and CO₂ into sugar.|Luz, agua, aire (CO₂), nutrientes y una temperatura adecuada. Con la luz, las hojas convierten el agua y el CO₂ en azúcar.|Lumière, eau, air (CO₂), nutriments et bonne température. Grâce à la lumière, les feuilles transforment l'eau et le CO₂ en sucre.|Llum, aigua, aire (CO₂), nutrients i una temperatura adequada. Amb la llum, les fulles converteixen l'aigua i el CO₂ en sucre.", Area.Biology, "Biology: photosynthesis|Biología: la fotosíntesis|Biologie : la photosynthèse|Biologia: la fotosíntesi"),
                C("soil", "Soil and compost|El suelo y el compost|Le sol et le compost|El sòl i el compost", "Soil is a mix of sand, silt, clay and organic matter; its texture decides how it holds water and air. Compost is organic matter transformed by living things.|El suelo es una mezcla de arena, limo, arcilla y materia orgánica; su textura decide cómo retiene el agua y el aire. El compost es materia orgánica transformada por seres vivos.|Le sol est un mélange de sable, limon, argile et matière organique ; sa texture décide comment il retient l'eau et l'air. Le compost est de la matière organique transformée par des êtres vivants.|El sòl és una barreja de sorra, llim, argila i matèria orgànica; la seva textura decideix com reté l'aigua i l'aire. El compost és matèria orgànica transformada per éssers vius.", Area.Chemistry, "Chemistry: pH and nutrients; biology: decomposers|Química: el pH y los nutrientes; biología: los descomponedores|Chimie : le pH et les nutriments ; biologie : les décomposeurs|Química: el pH i els nutrients; biologia: els descomponedors", "needs"),
                C("sowing", "Sowing and planting|Sembrar y plantar|Semer et planter|Sembrar i plantar", "A seed needs moisture and warmth to germinate; sow it at about 2 to 3 times its size; each plant has its season.|Una semilla necesita humedad y calor para germinar; se siembra a unas 2 o 3 veces su tamaño; cada planta tiene su estación.|Une graine a besoin d'humidité et de chaleur pour germer ; on la sème à environ 2 à 3 fois sa taille ; chaque plante a sa saison.|Una llavor necessita humitat i calor per germinar; se sembra a unes 2 o 3 vegades la seva mida; cada planta té la seva estació.", Area.Biology, "Biology: germination and life cycles|Biología: la germinación y los ciclos de vida|Biologie : la germination et les cycles de vie|Biologia: la germinació i els cicles de vida", "needs"),
                C("watering", "Watering|El riego|L'arrosage|El reg", "Water early or late, at the foot of the plant; drip irrigation and mulch save water by reducing evaporation.|Riega temprano o al atardecer, al pie de la planta; el goteo y el acolchado ahorran agua porque reducen la evaporación.|Arrose tôt ou tard, au pied de la plante ; le goutte-à-goutte et le paillage économisent l'eau en réduisant l'évaporation.|Rega d'hora o al vespre, al peu de la planta; el degoteig i l'encoixinat estalvien aigua perquè redueixen l'evaporació.", Area.Physics, "Physics: evaporation|Física: la evaporación|Physique : l'évaporation|Física: l'evaporació", "soil"),
                C("trees", "Flowers, fruit trees and pruning|Flores, frutales y poda|Fleurs, arbres fruitiers et taille|Flors, fruiters i poda", "Bees carry pollen from flower to flower so fruits can form; many fruit trees are pruned at the end of winter; grafting keeps a variety.|Las abejas llevan el polen de flor en flor para que se formen frutos; muchos frutales se podan a finales del invierno; el injerto conserva una variedad.|Les abeilles portent le pollen de fleur en fleur pour que les fruits se forment ; beaucoup d'arbres fruitiers se taillent à la fin de l'hiver ; la greffe conserve une variété.|Les abelles porten el pol·len de flor en flor perquè es formin fruits; molts fruiters es poden a finals de l'hivern; l'empelt conserva una varietat.", Area.Biology, "Biology: pollination and reproduction of plants|Biología: la polinización y la reproducción de las plantas|Biologie : la pollinisation et la reproduction des plantes|Biologia: la pol·linització i la reproducció de les plantes", "sowing"),
            ],
            [
                Q("needs", 2, "Where does a plant get most of the matter it uses to grow?|¿De dónde saca una planta la mayor parte de la materia con la que crece?|D'où une plante tire-t-elle la plus grande partie de la matière qui la fait grandir ?|D'on treu una planta la major part de la matèria amb què creix?", "From the CO₂ of the air, by photosynthesis|Del CO₂ del aire, por la fotosíntesis|Du CO₂ de l'air, par la photosynthèse|Del CO₂ de l'aire, per la fotosíntesi", "The carbon of the wood and the leaves comes from the air; the soil gives water and a small amount of minerals.|El carbono de la madera y las hojas viene del aire; el suelo da agua y una pequeña cantidad de minerales.|Le carbone du bois et des feuilles vient de l'air ; le sol donne l'eau et un peu de minéraux.|El carboni de la fusta i les fulles ve de l'aire; el sòl dona aigua i una petita quantitat de minerals.", "From the soil|De la tierra|De la terre|De la terra", "From fertiliser|Del abono|De l'engrais|De l'adob", "From the rain only|Solo de la lluvia|Seulement de la pluie|Només de la pluja"),
                Q("needs", 1, "A pale, long and thin plant usually lacks…|Una planta pálida, alargada y delgada suele tener falta de…|Une plante pâle, longue et fine manque en général de…|Una planta pàl·lida, allargada i prima sol tenir manca de…", "light|luz|lumière|llum", "It stretches looking for light (etiolation).|Se estira buscando la luz (ahilamiento).|Elle s'étire pour chercher la lumière (étiolement).|S'estira buscant la llum (ahilament).", "cold|frío|froid|fred", "fertiliser|abono|engrais|adob", "wind|viento|vent|vent"),
                Q("needs", 3, "Why do roots rot when a plant is watered too much?|¿Por qué se pudren las raíces si se riega demasiado?|Pourquoi les racines pourrissent-elles quand on arrose trop ?|Per què es podreixen les arrels si es rega massa?", "Waterlogged soil has no oxygen for the roots|En la tierra encharcada las raíces no tienen oxígeno|Dans la terre détrempée, les racines manquent d'oxygène|A la terra entollada les arrels no tenen oxigen", "Roots breathe: water fills the air spaces of the soil.|Las raíces respiran: el agua llena los huecos de aire del suelo.|Les racines respirent : l'eau remplit les espaces d'air du sol.|Les arrels respiren: l'aigua omple els buits d'aire del sòl.", "The water is too cold|El agua está demasiado fría|L'eau est trop froide|L'aigua és massa freda", "They drink too much sugar|Beben demasiado azúcar|Elles boivent trop de sucre|Beuen massa sucre", "The light cannot reach them|La luz no les llega|La lumière ne les atteint pas|La llum no hi arriba"),
                Q("soil", 1, "A sandy soil…|Un suelo arenoso…|Un sol sableux…|Un sòl sorrenc…", "drains fast and holds little water|drena rápido y retiene poca agua|draine vite et retient peu d'eau|drena ràpid i reté poca aigua", "Big grains leave big gaps: water goes through quickly.|Los granos grandes dejan huecos grandes: el agua pasa deprisa.|Les gros grains laissent de grands vides : l'eau passe vite.|Els grans grossos deixen buits grans: l'aigua passa de pressa.", "floods easily|se encharca con facilidad|se gorge d'eau facilement|s'entolla amb facilitat", "holds a lot of water|retiene mucha agua|retient beaucoup d'eau|reté molta aigua", "does not let air in|no deja pasar el aire|ne laisse pas passer l'air|no deixa passar l'aire"),
                Q("soil", 2, "Who turns kitchen and garden scraps into compost?|¿Quién transforma los restos de cocina y jardín en compost?|Qui transforme les restes de cuisine et de jardin en compost ?|Qui transforma les restes de cuina i jardí en compost?", "Bacteria, fungi and worms|Bacterias, hongos y lombrices|Les bactéries, les champignons et les vers|Bacteris, fongs i cucs", "These decomposers break down organic matter and give back nutrients.|Estos descomponedores deshacen la materia orgánica y devuelven nutrientes.|Ces décomposeurs dégradent la matière organique et rendent des nutriments.|Aquests descomponedors desfan la matèria orgànica i retornen nutrients.", "The sun alone|Solo el sol|Le soleil seul|Només el sol", "The roots|Las raíces|Les racines|Les arrels", "Plastic bags|Las bolsas de plástico|Les sacs en plastique|Les bosses de plàstic"),
                Q("soil", 3, "Most vegetables prefer a soil pH of about…|La mayoría de hortalizas prefieren un pH del suelo de…|La plupart des légumes préfèrent un pH du sol d'environ…|La majoria d'hortalisses prefereixen un pH del sòl de…", "6 to 7 (slightly acid to neutral)|6 a 7 (ligeramente ácido a neutro)|6 à 7 (légèrement acide à neutre)|6 a 7 (lleugerament àcid a neutre)", "In that range the nutrients dissolve best for the roots.|En ese rango los nutrientes se disuelven mejor para las raíces.|Dans cette zone, les nutriments se dissolvent le mieux pour les racines.|En aquest interval els nutrients es dissolen millor per a les arrels.", "3 (very acid)|3 (muy ácido)|3 (très acide)|3 (molt àcid)", "10 (very basic)|10 (muy básico)|10 (très basique)|10 (molt bàsic)", "It does not matter|Da igual|Ça n'a pas d'importance|Tant és"),
                Q("sowing", 1, "How deep is a seed usually sown?|¿A qué profundidad se siembra una semilla, en general?|À quelle profondeur sème-t-on une graine, en général ?|A quina fondària se sembra una llavor, en general?", "About 2 to 3 times its size|A unas 2 o 3 veces su tamaño|À environ 2 à 3 fois sa taille|A unes 2 o 3 vegades la seva mida", "Small seeds almost on the surface, big ones (beans) deeper.|Las semillas pequeñas casi en superficie y las grandes (judías) más hondas.|Les petites graines presque en surface, les grosses (haricots) plus profond.|Les llavors petites gairebé a la superfície i les grosses (mongetes) més fondes.", "30 cm", "10 times its size|10 veces su tamaño|10 fois sa taille|10 vegades la seva mida", "Always on the surface|Siempre en la superficie|Toujours en surface|Sempre a la superfície"),
                Q("sowing", 2, "To germinate, almost every seed needs above all…|Para germinar, casi todas las semillas necesitan sobre todo…|Pour germer, presque toutes les graines ont surtout besoin…|Per germinar, gairebé totes les llavors necessiten sobretot…", "moisture and a suitable temperature|humedad y una temperatura adecuada|d'humidité et d'une température adaptée|humitat i una temperatura adequada", "The seed has its own food reserve; water and warmth wake it up.|La semilla tiene su propia reserva de alimento; el agua y el calor la despiertan.|La graine a sa propre réserve de nourriture ; l'eau et la chaleur la réveillent.|La llavor té la seva pròpia reserva d'aliment; l'aigua i la calor la desperten.", "strong fertiliser|abono fuerte|un engrais fort|adob fort", "a lot of wind|mucho viento|beaucoup de vent|molt de vent", "full sun at midday|sol pleno a mediodía|plein soleil à midi|sol ple al migdia"),
                Q("sowing", 3, "The tomato is a summer plant: when is it planted outdoors?|El tomate es una planta de verano: ¿cuándo se planta al aire libre?|La tomate est une plante d'été : quand la plante-t-on dehors ?|La tomaquera és una planta d'estiu: quan es planta a l'aire lliure?", "In spring, when there is no more frost|En primavera, cuando ya no hiela|Au printemps, quand il ne gèle plus|A la primavera, quan ja no glaça", "Frost kills it; it needs warmth to flower and give fruit.|Las heladas la matan; necesita calor para florecer y dar fruto.|Le gel la tue ; elle a besoin de chaleur pour fleurir et donner des fruits.|Les glaçades la maten; necessita calor per florir i fer fruit.", "In December|En diciembre|En décembre|Al desembre", "In autumn, so it spends the winter outside|En otoño, para que pase el invierno fuera|En automne, pour qu'elle passe l'hiver dehors|A la tardor, perquè passi l'hivern fora", "Any time, it resists frost|En cualquier momento, aguanta las heladas|N'importe quand, elle résiste au gel|En qualsevol moment, aguanta les glaçades"),
                Q("watering", 1, "In summer, when is it best to water?|En verano, ¿cuándo es mejor regar?|En été, quand vaut-il mieux arroser ?|A l'estiu, quan és millor regar?", "Early in the morning or in the evening|Temprano por la mañana o al atardecer|Tôt le matin ou le soir|D'hora al matí o al vespre", "Less water evaporates when it is cooler.|Se evapora menos agua cuando hace menos calor.|Moins d'eau s'évapore quand il fait plus frais.|S'evapora menys aigua quan fa menys calor.", "At midday|A mediodía|À midi|Al migdia", "Never|Nunca|Jamais|Mai", "Only when it rains|Solo cuando llueve|Seulement quand il pleut|Només quan plou"),
                Q("watering", 2, "Mulch (straw, leaves) on the soil is used to…|El acolchado (paja, hojas) sobre la tierra sirve para…|Le paillage (paille, feuilles) sur le sol sert à…|L'encoixinat (palla, fulles) sobre la terra serveix per…", "reduce evaporation and weeds|reducir la evaporación y las malas hierbas|réduire l'évaporation et les mauvaises herbes|reduir l'evaporació i les males herbes", "It shades the soil and keeps it moist; later it becomes compost.|Da sombra al suelo y lo mantiene húmedo; con el tiempo se convierte en compost.|Il ombrage le sol et le garde humide ; avec le temps, il devient du compost.|Fa ombra al sòl i el manté humit; amb el temps es converteix en compost.", "attract the sun|atraer el sol|attirer le soleil|atreure el sol", "harden the soil|endurecer la tierra|durcir la terre|endurir la terra", "make the plants grow faster at night|que las plantas crezcan más de noche|faire pousser les plantes plus vite la nuit|que les plantes creixin més de nit"),
                Q("watering", 3, "Why does drip irrigation save water?|¿Por qué el riego por goteo ahorra agua?|Pourquoi le goutte-à-goutte économise-t-il l'eau ?|Per què el reg per degoteig estalvia aigua?", "It brings water slowly to the foot of each plant|Lleva el agua despacio al pie de cada planta|Il apporte l'eau lentement au pied de chaque plante|Porta l'aigua a poc a poc al peu de cada planta", "Little water runs off or evaporates, and the leaves stay dry (fewer diseases).|Se pierde poca agua por escorrentía o evaporación, y las hojas quedan secas (menos enfermedades).|Peu d'eau ruisselle ou s'évapore, et les feuilles restent sèches (moins de maladies).|Es perd poca aigua per escolament o evaporació, i les fulles queden seques (menys malalties).", "It wets all the leaves|Moja todas las hojas|Il mouille toutes les feuilles|Mulla totes les fulles", "It uses hot water|Usa agua caliente|Il utilise de l'eau chaude|Fa servir aigua calenta", "It only works in winter|Solo funciona en invierno|Il ne marche qu'en hiver|Només funciona a l'hivern"),
                Q("trees", 1, "What do bees do for fruit trees?|¿Qué hacen las abejas por los frutales?|Que font les abeilles pour les arbres fruitiers ?|Què fan les abelles pels fruiters?", "They carry pollen from flower to flower|Llevan el polen de flor en flor|Elles portent le pollen de fleur en fleur|Porten el pol·len de flor en flor", "Pollination fertilises the flower, which becomes a fruit with seeds.|La polinización fecunda la flor, que se convierte en un fruto con semillas.|La pollinisation féconde la fleur, qui devient un fruit avec des graines.|La pol·linització fecunda la flor, que es converteix en un fruit amb llavors.", "They water them|Las riegan|Elles les arrosent|Les reguen", "They eat the seeds|Se comen las semillas|Elles mangent les graines|Es mengen les llavors", "They make the fruit with honey|Fabrican el fruto con miel|Elles fabriquent le fruit avec du miel|Fabriquen el fruit amb mel"),
                Q("trees", 2, "Many deciduous fruit trees are pruned mainly…|Muchos frutales de hoja caduca se podan sobre todo…|Beaucoup d'arbres fruitiers à feuilles caduques se taillent surtout…|Molts fruiters de fulla caduca es poden sobretot…", "at the end of winter, while they rest|a finales del invierno, durante el reposo|à la fin de l'hiver, pendant le repos|a finals de l'hivern, durant el repòs", "Without leaves you see the branches, and the tree heals when it wakes up in spring.|Sin hojas se ven bien las ramas, y el árbol cicatriza al despertar en primavera.|Sans feuilles, on voit bien les branches, et l'arbre cicatrise en se réveillant au printemps.|Sense fulles es veuen bé les branques, i l'arbre cicatritza en despertar-se a la primavera.", "in full bloom|en plena floración|en pleine floraison|en plena floració", "at midday in summer|al mediodía en verano|à midi en été|al migdia a l'estiu", "never|nunca|jamais|mai"),
                Q("trees", 3, "To get the same apple as the mother tree, gardeners use…|Para obtener la misma manzana que el árbol madre, se usa…|Pour obtenir la même pomme que l'arbre mère, on utilise…|Per obtenir la mateixa poma que l'arbre mare, es fa servir…", "grafting|el injerto|la greffe|l'empelt", "A seed mixes genes of two parents and gives a different apple; a graft is a copy of the variety.|Una semilla mezcla genes de dos progenitores y da otra manzana; el injerto es una copia de la variedad.|Une graine mélange les gènes de deux parents et donne une autre pomme ; la greffe est une copie de la variété.|Una llavor barreja gens de dos progenitors i dona una altra poma; l'empelt és una còpia de la varietat.", "its seeds|sus semillas|ses graines|les seves llavors", "more water|más riego|plus d'eau|més aigua", "more fertiliser|más abono|plus d'engrais|més adob"),
            ]),
        new("trade-plumbing", "🔧", "sky",
            Txt.Of("Plumbing|Fontanería|Plomberie|Lampisteria"),
            Txt.Of("Water at home: pressure, pipes and materials, traps and drains, leaks and repairs, hard water and limescale.|El agua en casa: presión, tuberías y materiales, sifones y desagües, fugas y averías, agua dura y cal.|L'eau à la maison : pression, tuyaux et matériaux, siphons et évacuations, fuites et réparations, eau dure et calcaire.|L'aigua a casa: pressió, canonades i materials, sifons i desguassos, fuites i avaries, aigua dura i calç."),
            Txt.Of("Theory only. For gas and for any work on the installation, call an authorised professional.|Solo teoría. Para el gas y para cualquier obra en la instalación, llama a un profesional autorizado.|Théorie uniquement. Pour le gaz et pour tout travail sur l'installation, appelle un professionnel agréé.|Només teoria. Per al gas i per a qualsevol obra a la instal·lació, truca a un professional autoritzat."),
            [
                C("pressure", "Water pressure|La presión del agua|La pression de l'eau|La pressió de l'aigua", "Pressure is force per area. Every 10 m of water height gives about 1 bar; homes usually have 2 to 4 bar.|La presión es fuerza por superficie. Cada 10 m de altura de agua dan aproximadamente 1 bar; las casas suelen tener de 2 a 4 bar.|La pression est une force par surface. Chaque 10 m de hauteur d'eau donne environ 1 bar ; les maisons ont en général 2 à 4 bar.|La pressió és força per superfície. Cada 10 m d'alçada d'aigua donen aproximadament 1 bar; les cases solen tenir de 2 a 4 bar.", Area.Physics, "Physics: pressure and gravity|Física: la presión y la gravedad|Physique : la pression et la gravité|Física: la pressió i la gravetat"),
                C("pipes", "Pipes and materials|Tuberías y materiales|Tuyaux et matériaux|Canonades i materials", "Copper, multilayer or PEX for drinking water, PVC for drains. A narrower pipe gives less flow; some metals must not touch.|Cobre, multicapa o PEX para el agua potable, PVC para los desagües. Una tubería más estrecha da menos caudal; algunos metales no deben tocarse.|Cuivre, multicouche ou PER pour l'eau potable, PVC pour les évacuations. Un tuyau plus étroit donne moins de débit ; certains métaux ne doivent pas se toucher.|Coure, multicapa o PEX per a l'aigua potable, PVC per als desguassos. Una canonada més estreta dona menys cabal; alguns metalls no s'han de tocar.", Area.Chemistry, "Chemistry: materials and corrosion|Química: los materiales y la corrosión|Chimie : les matériaux et la corrosion|Química: els materials i la corrosió", "pressure"),
                C("drains", "Traps and drains|Sifones y desagües|Siphons et évacuations|Sifons i desguassos", "A trap keeps some water that blocks smells; drains need a small slope so water flows by gravity.|El sifón guarda un poco de agua que bloquea los olores; los desagües necesitan una pequeña pendiente para que el agua baje por gravedad.|Le siphon garde un peu d'eau qui bloque les odeurs ; les évacuations ont besoin d'une petite pente pour que l'eau descende par gravité.|El sifó guarda una mica d'aigua que bloqueja les olors; els desguassos necessiten un petit pendent perquè l'aigua baixi per gravetat.", Area.Physics, "Physics: gravity and communicating vessels|Física: la gravedad y los vasos comunicantes|Physique : la gravité et les vases communicants|Física: la gravetat i els vasos comunicants", "pressure"),
                C("leaks", "Leaks and repairs|Fugas y averías|Fuites et réparations|Fuites i avaries", "First close the stopcock. A dripping tap usually needs a new washer or cartridge; the meter shows hidden leaks.|Lo primero, cerrar la llave de paso. Un grifo que gotea suele necesitar una zapata o un cartucho nuevo; el contador revela las fugas ocultas.|D'abord, fermer le robinet d'arrêt. Un robinet qui goutte a souvent besoin d'un joint ou d'une cartouche neufs ; le compteur révèle les fuites cachées.|El primer, tancar la clau de pas. Una aixeta que degota sol necessitar una zapata o un cartutx nou; el comptador revela les fuites ocultes.", Area.Mathematics, "Mathematics: estimating volumes|Matemáticas: estimar volúmenes|Mathématiques : estimer des volumes|Matemàtiques: estimar volums", "pipes"),
                C("limescale", "Hard water and limescale|Agua dura y cal|Eau dure et calcaire|Aigua dura i calç", "Hard water carries dissolved calcium; with heat it deposits calcium carbonate (limescale). An acid like vinegar dissolves it.|El agua dura lleva calcio disuelto; con el calor deposita carbonato de calcio (la cal). Un ácido como el vinagre la disuelve.|L'eau dure contient du calcium dissous ; avec la chaleur, elle dépose du carbonate de calcium (le calcaire). Un acide comme le vinaigre le dissout.|L'aigua dura porta calci dissolt; amb la calor diposita carbonat de calci (la calç). Un àcid com el vinagre la dissol.", Area.Chemistry, "Chemistry: acids, bases and precipitation|Química: ácidos, bases y precipitación|Chimie : acides, bases et précipitation|Química: àcids, bases i precipitació", "pipes"),
            ],
            [
                Q("pressure", 1, "What is the usual water pressure in a home?|¿Qué presión de agua suele haber en una vivienda?|Quelle est la pression d'eau habituelle dans un logement ?|Quina pressió d'aigua sol haver-hi en un habitatge?", "2 to 4 bar|De 2 a 4 bar|2 à 4 bar|De 2 a 4 bar", "Less gives weak showers; much more can damage taps and appliances.|Menos da duchas flojas; mucha más puede dañar grifos y electrodomésticos.|Moins donne des douches faibles ; beaucoup plus peut abîmer robinets et appareils.|Menys dona dutxes fluixes; molta més pot fer malbé aixetes i electrodomèstics.", "20 to 40 bar|De 20 a 40 bar|20 à 40 bar|De 20 a 40 bar", "0.01 bar|0,01 bar|0,01 bar|0,01 bar", "200 bar"),
                Q("pressure", 2, "A tank 10 m higher than a tap gives a pressure of about…|Un depósito 10 m más alto que un grifo da una presión de aproximadamente…|Un réservoir placé 10 m plus haut qu'un robinet donne une pression d'environ…|Un dipòsit 10 m més alt que una aixeta dona una pressió d'aproximadament…", "1 bar", "The weight of a 10 m column of water is about 1 bar.|El peso de una columna de agua de 10 m equivale a 1 bar.|Le poids d'une colonne d'eau de 10 m vaut environ 1 bar.|El pes d'una columna d'aigua de 10 m equival a 1 bar.", "10 bar", "0.1 bar|0,1 bar|0,1 bar|0,1 bar", "100 bar"),
                Q("pressure", 3, "Why does water come out with less pressure on a top floor?|¿Por qué el agua sale con menos presión en un piso alto?|Pourquoi l'eau sort-elle avec moins de pression à un étage élevé ?|Per què l'aigua surt amb menys pressió en un pis alt?", "The water has to rise against gravity: pressure falls with height|El agua tiene que subir contra la gravedad: la presión baja con la altura|L'eau doit monter contre la gravité : la pression baisse avec la hauteur|L'aigua ha de pujar contra la gravetat: la pressió baixa amb l'alçada", "About 0.1 bar is lost per metre of height.|Se pierde alrededor de 0,1 bar por metro de altura.|On perd environ 0,1 bar par mètre de hauteur.|Es perd al voltant de 0,1 bar per metre d'alçada.", "The water gets tired|El agua se cansa|L'eau se fatigue|L'aigua es cansa", "The pipes are made of copper|Las tuberías son de cobre|Les tuyaux sont en cuivre|Les canonades són de coure", "The water gets warmer|El agua se calienta|L'eau se réchauffe|L'aigua s'escalfa"),
                Q("pipes", 1, "Which material is widely used for drains?|¿Qué material se usa mucho en los desagües?|Quel matériau est très utilisé pour les évacuations ?|Quin material es fa servir molt als desguassos?", "PVC", "It is light, cheap and does not rust.|Es ligero, barato y no se oxida.|Il est léger, bon marché et ne rouille pas.|És lleuger, barat i no s'oxida.", "Glass|El vidrio|Le verre|El vidre", "Paper|El papel|Le papier|El paper", "Unprotected iron|El hierro sin proteger|Le fer non protégé|El ferro sense protegir"),
                Q("pipes", 2, "With the same pressure, a narrower pipe gives a flow that is…|Con la misma presión, una tubería más estrecha da un caudal…|À pression égale, un tuyau plus étroit donne un débit…|Amb la mateixa pressió, una canonada més estreta dona un cabal…", "smaller|menor|plus faible|menor", "Less section and more friction: less water per second.|Menos sección y más rozamiento: menos agua por segundo.|Moins de section et plus de frottement : moins d'eau par seconde.|Menys secció i més fregament: menys aigua per segon.", "bigger|mayor|plus fort|major", "the same|igual|identique|igual", "frozen|congelado|gelé|congelat"),
                Q("pipes", 3, "Joining copper directly to galvanised steel can cause…|Unir directamente cobre con acero galvanizado puede causar…|Relier directement du cuivre à de l'acier galvanisé peut provoquer…|Unir directament coure amb acer galvanitzat pot causar…", "galvanic corrosion|corrosión galvánica|une corrosion galvanique|corrosió galvànica", "Two different metals in water form a small battery: one of them corrodes. A dielectric fitting separates them.|Dos metales distintos en agua forman una pequeña pila: uno de ellos se corroe. Un manguito dieléctrico los separa.|Deux métaux différents dans l'eau forment une petite pile : l'un d'eux se corrode. Un raccord diélectrique les sépare.|Dos metalls diferents en aigua formen una petita pila: un d'ells es corroeix. Un maneguet dielèctric els separa.", "more pressure|más presión|plus de pression|més pressió", "hot water|agua caliente|de l'eau chaude|aigua calenta", "nothing|nada|rien|res"),
                Q("drains", 1, "What is the trap under a washbasin for?|¿Para qué sirve el sifón de un lavabo?|À quoi sert le siphon sous un lavabo ?|Per a què serveix el sifó d'un lavabo?", "Its water blocks the smells of the drain|Su agua bloquea los olores del desagüe|Son eau bloque les odeurs de l'évacuation|La seva aigua bloqueja les olors del desguàs", "The water kept in the bend acts like a plug for gases.|El agua que queda en la curva hace de tapón para los gases.|L'eau qui reste dans le coude fait bouchon pour les gaz.|L'aigua que queda a la corba fa de tap per als gasos.", "It raises the pressure|Aumenta la presión|Il augmente la pression|Augmenta la pressió", "It heats the water|Calienta el agua|Il chauffe l'eau|Escalfa l'aigua", "It filters limescale|Filtra la cal|Il filtre le calcaire|Filtra la calç"),
                Q("drains", 2, "Horizontal drain pipes need…|Los desagües horizontales necesitan…|Les évacuations horizontales ont besoin…|Els desguassos horitzontals necessiten…", "a small slope|una pequeña pendiente|d'une petite pente|un petit pendent", "Without pressure, water only flows downhill.|Sin presión, el agua solo corre cuesta abajo.|Sans pression, l'eau ne coule que vers le bas.|Sense pressió, l'aigua només corre costa avall.", "to be perfectly flat|ser totalmente horizontales|d'être parfaitement plates|ser totalment horitzontals", "to go up|subir|de monter|pujar", "many 90° bends in a row|muchos codos de 90° seguidos|de nombreux coudes à 90° à la suite|molts colzes de 90° seguits"),
                Q("drains", 3, "A drain smells bad after the holidays. The most likely reason is…|Un desagüe huele mal después de las vacaciones. Lo más probable es que…|Une évacuation sent mauvais après les vacances. Le plus probable est que…|Un desguàs fa pudor després de les vacances. El més probable és que…", "the water of the trap evaporated: let water run|el agua del sifón se evaporó: basta con dejar correr agua|l'eau du siphon s'est évaporée : il suffit de faire couler de l'eau|l'aigua del sifó s'ha evaporat: n'hi ha prou de deixar córrer aigua", "Without water, the trap no longer blocks the gases.|Sin agua, el sifón ya no bloquea los gases.|Sans eau, le siphon ne bloque plus les gaz.|Sense aigua, el sifó ja no bloqueja els gasos.", "the pipe must be changed|hay que cambiar la tubería|il faut changer le tuyau|cal canviar la canonada", "the pressure went up|la presión subió|la pression a augmenté|la pressió ha pujat", "the water froze|el agua se congeló|l'eau a gelé|l'aigua s'ha congelat"),
                Q("leaks", 1, "There is a leak: what is the first thing to do?|Hay una fuga: ¿qué es lo primero que hay que hacer?|Il y a une fuite : quelle est la première chose à faire ?|Hi ha una fuita: què és el primer que cal fer?", "Close the stopcock|Cerrar la llave de paso|Fermer le robinet d'arrêt|Tancar la clau de pas", "It stops the water from entering the home while you repair or call for help.|Detiene la entrada de agua mientras reparas o pides ayuda.|Elle arrête l'arrivée d'eau pendant que tu répares ou appelles à l'aide.|Atura l'entrada d'aigua mentre repares o demanes ajuda.", "Open all the taps|Abrir todos los grifos|Ouvrir tous les robinets|Obrir totes les aixetes", "Dry it and wait|Secar y esperar|Essuyer et attendre|Eixugar i esperar", "Raise the pressure|Subir la presión|Augmenter la pression|Pujar la pressió"),
                Q("leaks", 2, "How can you find out if there is a hidden leak?|¿Cómo saber si hay una fuga oculta?|Comment savoir s'il y a une fuite cachée ?|Com saber si hi ha una fuita oculta?", "Close every tap and see if the meter keeps turning|Cerrar todos los grifos y ver si el contador sigue moviéndose|Fermer tous les robinets et voir si le compteur continue de tourner|Tancar totes les aixetes i veure si el comptador continua girant", "If nobody uses water but the meter moves, water is escaping somewhere.|Si nadie usa agua y el contador se mueve, el agua se escapa por algún sitio.|Si personne n'utilise d'eau et que le compteur tourne, l'eau s'échappe quelque part.|Si ningú no fa servir aigua i el comptador es mou, l'aigua s'escapa per algun lloc.", "Smell the pipes|Oler las tuberías|Sentir les tuyaux|Olorar les canonades", "Look at the gas bill|Mirar la factura del gas|Regarder la facture de gaz|Mirar la factura del gas", "Raise the pressure|Subir la presión|Augmenter la pression|Pujar la pressió"),
                Q("leaks", 3, "A tap dripping one drop per second loses in a year about…|Un grifo que gotea una gota por segundo pierde al año unos…|Un robinet qui goutte une goutte par seconde perd en un an environ…|Una aixeta que degota una gota per segon perd a l'any uns…", "more than 1,000 litres|más de 1 000 litros|plus de 1 000 litres|més de 1.000 litres", "About 86,400 drops a day, around 4 litres: more than 1,000 litres a year.|Unas 86 400 gotas al día, unos 4 litros: más de 1 000 litros al año.|Environ 86 400 gouttes par jour, à peu près 4 litres : plus de 1 000 litres par an.|Unes 86.400 gotes al dia, uns 4 litres: més de 1.000 litres l'any.", "1 litre|1 litro|1 litre|1 litre", "10 litres|10 litros|10 litres|10 litres", "nothing important|nada importante|rien d'important|res important"),
                Q("limescale", 1, "The limescale in a kettle or water heater is mostly…|La cal de un hervidor o un calentador es sobre todo…|Le calcaire d'une bouilloire ou d'un chauffe-eau est surtout…|La calç d'un bullidor o un escalfador és sobretot…", "calcium carbonate|carbonato de calcio|du carbonate de calcium|carbonat de calci", "It is the same substance as limestone and chalk.|Es la misma sustancia que la piedra caliza y la tiza.|C'est la même substance que le calcaire et la craie.|És la mateixa substància que la pedra calcària i el guix.", "table salt|sal de mesa|du sel de table|sal de taula", "sugar|azúcar|du sucre|sucre", "rust|óxido|de la rouille|rovell"),
                Q("limescale", 2, "Why is there more limescale where water is heated?|¿Por qué hay más cal donde se calienta el agua?|Pourquoi y a-t-il plus de calcaire là où l'eau est chauffée ?|Per què hi ha més calç on s'escalfa l'aigua?", "Heat makes calcium carbonate come out of the water|El calor hace que el carbonato de calcio salga del agua|La chaleur fait sortir le carbonate de calcium de l'eau|La calor fa que el carbonat de calci surti de l'aigua", "Warm water holds less dissolved CO₂, so calcium carbonate precipitates.|El agua caliente retiene menos CO₂ disuelto y el carbonato de calcio precipita.|L'eau chaude retient moins de CO₂ dissous, donc le carbonate de calcium précipite.|L'aigua calenta reté menys CO₂ dissolt i el carbonat de calci precipita.", "Heat makes calcium|El calor fabrica calcio|La chaleur fabrique du calcium|La calor fabrica calci", "Cold water has more chlorine|El agua fría tiene más cloro|L'eau froide a plus de chlore|L'aigua freda té més clor", "The pipe melts|La tubería se derrite|Le tuyau fond|La canonada es fon"),
                Q("limescale", 3, "To remove limescale from a shower head, you can soak it in…|Para quitar la cal de una alcachofa de ducha se puede sumergir en…|Pour enlever le calcaire d'un pommeau de douche, on peut le tremper dans…|Per treure la calç d'un capçal de dutxa es pot submergir en…", "vinegar (a mild acid)|vinagre (un ácido suave)|du vinaigre (un acide doux)|vinagre (un àcid suau)", "The acid reacts with the carbonate and dissolves it, giving off CO₂ bubbles.|El ácido reacciona con el carbonato y lo disuelve, soltando burbujas de CO₂.|L'acide réagit avec le carbonate et le dissout, en libérant des bulles de CO₂.|L'àcid reacciona amb el carbonat i el dissol, deixant anar bombolles de CO₂.", "oil|aceite|de l'huile|oli", "salt water|agua con sal|de l'eau salée|aigua amb sal", "hot water only|solo agua caliente|de l'eau chaude seule|només aigua calenta"),
            ]),
        new("trade-carpentry", "🪚", "peach",
            Txt.Of("Carpentry|Carpintería|Menuiserie|Fusteria"),
            Txt.Of("Working with wood: the material, measuring and marking, tools and levers, joints and glue, finishing and safety.|Trabajar la madera: el material, medir y trazar, herramientas y palancas, uniones y colas, acabado y seguridad.|Travailler le bois : le matériau, mesurer et tracer, outils et leviers, assemblages et colles, finition et sécurité.|Treballar la fusta: el material, mesurar i traçar, eines i palanques, unions i coles, acabat i seguretat."),
            Txt.Of("Theory only. Power tools are used with an adult or a professional, with glasses, mask and hearing protection.|Solo teoría. Las herramientas eléctricas se usan con un adulto o un profesional, con gafas, mascarilla y protección auditiva.|Théorie uniquement. Les outils électriques s'utilisent avec un adulte ou un professionnel, avec lunettes, masque et protection auditive.|Només teoria. Les eines elèctriques es fan servir amb un adult o un professional, amb ulleres, mascareta i protecció auditiva."),
            [
                C("wood", "Wood, a living material|La madera, un material vivo|Le bois, un matériau vivant|La fusta, un material viu", "Wood is the tissue of a tree: each ring is usually one year. It swells and shrinks with moisture; conifers give softwood, broadleaf trees hardwood.|La madera es el tejido de un árbol: cada anillo suele ser un año. Se hincha y encoge con la humedad; las coníferas dan madera blanda y las frondosas, dura.|Le bois est le tissu d'un arbre : chaque cerne correspond en général à un an. Il gonfle et rétrécit avec l'humidité ; les conifères donnent du bois tendre, les feuillus du bois dur.|La fusta és el teixit d'un arbre: cada anell sol ser un any. S'infla i s'encongeix amb la humitat; les coníferes donen fusta tova i les frondoses, dura.", Area.Biology, "Biology: how trees grow|Biología: cómo crecen los árboles|Biologie : comment poussent les arbres|Biologia: com creixen els arbres"),
                C("measure", "Measuring and marking|Medir y trazar|Mesurer et tracer|Mesurar i traçar", "Measure twice, cut once. A square checks 90°; the 3-4-5 rule (Pythagoras) checks a right angle; remember the width of the saw cut.|Mide dos veces y corta una. La escuadra comprueba los 90°; la regla 3-4-5 (Pitágoras) comprueba un ángulo recto; ten en cuenta el grosor del corte de la sierra.|Mesure deux fois, coupe une fois. L'équerre vérifie les 90° ; la règle 3-4-5 (Pythagore) vérifie un angle droit ; compte l'épaisseur du trait de scie.|Mesura dues vegades i talla'n una. L'escaire comprova els 90°; la regla 3-4-5 (Pitàgores) comprova un angle recte; tingues en compte el gruix del tall de la serra.", Area.Mathematics, "Mathematics: Pythagoras and measurement|Matemáticas: Pitágoras y la medida|Mathématiques : Pythagore et la mesure|Matemàtiques: Pitàgores i la mesura", "wood"),
                C("tools", "Tools and levers|Herramientas y palancas|Outils et leviers|Eines i palanques", "A longer handle multiplies force (lever); a pilot hole stops screws from splitting wood; the spirit level checks horizontal and vertical.|Un mango más largo multiplica la fuerza (palanca); un agujero guía evita que el tornillo raje la madera; el nivel comprueba lo horizontal y lo vertical.|Un manche plus long multiplie la force (levier) ; un avant-trou empêche la vis de fendre le bois ; le niveau vérifie l'horizontale et la verticale.|Un mànec més llarg multiplica la força (palanca); un forat guia evita que el cargol esberli la fusta; el nivell comprova l'horitzontal i la vertical.", Area.Physics, "Physics: levers and forces|Física: palancas y fuerzas|Physique : leviers et forces|Física: palanques i forces", "measure"),
                C("joints", "Joints and glue|Uniones y colas|Assemblages et colles|Unions i coles", "Wood glue (PVA) hardens when its water leaves; clamps hold the pieces while it dries. Mortise and tenon: a tongue of one piece fits a hole of the other.|La cola blanca (PVA) endurece cuando pierde el agua; los sargentos sujetan las piezas mientras seca. Caja y espiga: un saliente de una pieza encaja en un hueco de la otra.|La colle vinylique (PVA) durcit quand son eau s'en va ; les serre-joints tiennent les pièces pendant le séchage. Tenon et mortaise : une languette d'une pièce entre dans un trou de l'autre.|La cola blanca (PVA) s'endureix quan perd l'aigua; els serjants subjecten les peces mentre s'asseca. Metxa i encaix: un sortint d'una peça encaixa en un forat de l'altra.", Area.Chemistry, "Chemistry: how glues harden|Química: cómo endurecen las colas|Chimie : comment durcissent les colles|Química: com s'endureixen les coles", "tools"),
                C("finish", "Finishing and safety|Acabado y seguridad|Finition et sécurité|Acabat i seguretat", "Sand from coarse to fine grit along the grain; varnish or oil protect from moisture; glasses, dust mask and hearing protection.|Se lija de grano grueso a fino a favor de la veta; el barniz o el aceite protegen de la humedad; gafas, mascarilla y protección auditiva.|On ponce du grain gros au grain fin dans le sens du fil ; le vernis ou l'huile protègent de l'humidité ; lunettes, masque et protection auditive.|Es poleix de gra gruixut a fi a favor de la veta; el vernís o l'oli protegeixen de la humitat; ulleres, mascareta i protecció auditiva.", Area.Biology, "Biology: protecting the lungs and the ears|Biología: proteger los pulmones y los oídos|Biologie : protéger les poumons et les oreilles|Biologia: protegir els pulmons i les oïdes", "joints"),
            ],
            [
                Q("wood", 1, "Each ring of a tree trunk usually corresponds to…|Cada anillo del tronco de un árbol suele corresponder a…|Chaque cerne d'un tronc d'arbre correspond en général à…|Cada anell del tronc d'un arbre sol correspondre a…", "one year of growth|un año de crecimiento|une année de croissance|un any de creixement", "In spring the wood grows fast and light, in summer slower and darker: one ring per year.|En primavera la madera crece rápida y clara, en verano más lenta y oscura: un anillo por año.|Au printemps le bois pousse vite et clair, en été plus lentement et plus foncé : un cerne par an.|A la primavera la fusta creix ràpida i clara, a l'estiu més lenta i fosca: un anell per any.", "one month|un mes|un mois|un mes", "one week|una semana|une semaine|una setmana", "one pruning|una poda|une taille|una poda"),
                Q("wood", 2, "Wood swells mainly when…|La madera se hincha sobre todo cuando…|Le bois gonfle surtout quand…|La fusta s'infla sobretot quan…", "it absorbs moisture|absorbe humedad|il absorbe de l'humidité|absorbeix humitat", "Wood cells take in water and expand; that is why doors stick in wet weather.|Las células de la madera absorben agua y se dilatan; por eso las puertas rozan cuando hay humedad.|Les cellules du bois absorbent l'eau et gonflent ; c'est pour ça que les portes frottent par temps humide.|Les cèl·lules de la fusta absorbeixen aigua i es dilaten; per això les portes freguen quan hi ha humitat.", "it is cold|hace frío|il fait froid|fa fred", "it is painted|se pinta|on le peint|es pinta", "it is cut in summer|se corta en verano|on le coupe en été|es talla a l'estiu"),
                Q("wood", 3, "Pine and fir give, in general, a wood that is…|El pino y el abeto dan, en general, una madera…|Le pin et le sapin donnent, en général, un bois…|El pi i l'avet donen, en general, una fusta…", "soft (conifers)|blanda (coníferas)|tendre (conifères)|tova (coníferes)", "Conifers grow fast and give softwood; oak or walnut (broadleaf) give hardwood.|Las coníferas crecen rápido y dan madera blanda; el roble o el nogal (frondosas) dan madera dura.|Les conifères poussent vite et donnent du bois tendre ; le chêne ou le noyer (feuillus) donnent du bois dur.|Les coníferes creixen ràpid i donen fusta tova; el roure o la noguera (frondoses) donen fusta dura.", "hard (broadleaf)|dura (frondosas)|dur (feuillus)|dura (frondoses)", "tropical|tropical|tropical|tropical", "artificial|artificial|artificiel|artificial"),
                Q("measure", 1, "Which tool checks a 90° angle?|¿Qué herramienta comprueba un ángulo de 90°?|Quel outil vérifie un angle de 90° ?|Quina eina comprova un angle de 90°?", "The square|La escuadra|L'équerre|L'escaire", "Put it on the corner: if both sides touch, the angle is right.|Se apoya en la esquina: si los dos lados tocan, el ángulo es recto.|On la pose dans le coin : si les deux côtés touchent, l'angle est droit.|Es recolza a la cantonada: si els dos costats toquen, l'angle és recte.", "The spirit level|El nivel|Le niveau|El nivell", "Sandpaper|La lija|Le papier de verre|El paper de vidre", "The chisel|El formón|Le ciseau à bois|L'enformador"),
                Q("measure", 2, "To check a corner, measure 3 on one side and 4 on the other. If the angle is right, the diagonal measures…|Para comprobar una esquina se mide 3 en un lado y 4 en el otro. Si el ángulo es recto, la diagonal mide…|Pour vérifier un coin, on mesure 3 sur un côté et 4 sur l'autre. Si l'angle est droit, la diagonale mesure…|Per comprovar una cantonada es mesura 3 en un costat i 4 a l'altre. Si l'angle és recte, la diagonal mesura…", "5", "Pythagoras: 3² + 4² = 9 + 16 = 25 = 5².|Pitágoras: 3² + 4² = 9 + 16 = 25 = 5².|Pythagore : 3² + 4² = 9 + 16 = 25 = 5².|Pitàgores: 3² + 4² = 9 + 16 = 25 = 5².", "7", "6", "4"),
                Q("measure", 3, "A 2.40 m board is cut into 4 equal pieces with 3 cuts; the saw removes 3 mm per cut. Each piece measures about…|Un tablero de 2,40 m se corta en 4 piezas iguales con 3 cortes; la sierra se lleva 3 mm por corte. Cada pieza mide unos…|Une planche de 2,40 m est coupée en 4 pièces égales avec 3 coupes ; la scie enlève 3 mm par coupe. Chaque pièce mesure environ…|Un tauler de 2,40 m es talla en 4 peces iguals amb 3 talls; la serra s'emporta 3 mm per tall. Cada peça mesura uns…", "59.8 cm|59,8 cm|59,8 cm|59,8 cm", "(2400 − 3 × 3) ÷ 4 = 597.75 mm ≈ 59.8 cm.|(2400 − 3 × 3) ÷ 4 = 597,75 mm ≈ 59,8 cm.|(2400 − 3 × 3) ÷ 4 = 597,75 mm ≈ 59,8 cm.|(2400 − 3 × 3) ÷ 4 = 597,75 mm ≈ 59,8 cm.", "60 cm", "80 cm", "57 cm"),
                Q("tools", 1, "What does a spirit level check?|¿Qué comprueba un nivel de burbuja?|Que vérifie un niveau à bulle ?|Què comprova un nivell de bombolla?", "That a surface is horizontal or vertical|Que una superficie está horizontal o vertical|Qu'une surface est horizontale ou verticale|Que una superfície està horitzontal o vertical", "The bubble goes to the highest point of the curved tube: centred means level.|La burbuja va al punto más alto del tubo curvo: centrada significa a nivel.|La bulle va au point le plus haut du tube courbé : centrée veut dire de niveau.|La bombolla va al punt més alt del tub corbat: centrada vol dir a nivell.", "That it is smooth|Que está lisa|Qu'elle est lisse|Que està llisa", "That it is dry|Que está seca|Qu'elle est sèche|Que està seca", "That it is at 45°|Que está a 45°|Qu'elle est à 45°|Que està a 45°"),
                Q("tools", 2, "To drive a screw near the edge without splitting the wood, first…|Para meter un tornillo cerca del borde sin rajar la madera, antes se hace…|Pour visser près du bord sans fendre le bois, on fait d'abord…|Per posar un cargol a prop de la vora sense esberlar la fusta, abans es fa…", "a pilot hole|un agujero guía|un avant-trou|un forat guia", "The hole makes room for the screw, so it does not wedge the fibres apart.|El agujero hace sitio al tornillo para que no separe las fibras como una cuña.|Le trou fait de la place à la vis pour qu'elle n'écarte pas les fibres comme un coin.|El forat fa lloc al cargol perquè no separi les fibres com una falca.", "you wet the screw|se moja el tornillo|on mouille la vis|es mulla el cargol", "you heat the wood|se calienta la madera|on chauffe le bois|s'escalfa la fusta", "you hit it with a hammer|se golpea con el martillo|on la tape au marteau|es pica amb el martell"),
                Q("tools", 3, "With a longer pry bar, to pull out the same nail you need…|Con una palanca más larga, para sacar el mismo clavo necesitas…|Avec un pied-de-biche plus long, pour arracher le même clou il faut…|Amb una palanca més llarga, per treure el mateix clau necessites…", "less force|menos fuerza|moins de force|menys força", "Force × arm is the same: a longer arm means less force (but you move it further).|Fuerza × brazo es lo mismo: un brazo más largo significa menos fuerza (pero lo mueves más).|Force × bras reste la même : un bras plus long veut dire moins de force (mais on le déplace plus loin).|Força × braç és el mateix: un braç més llarg vol dir menys força (però el mous més).", "more force|más fuerza|plus de force|més força", "the same force|la misma fuerza|la même force|la mateixa força", "no force at all|ninguna fuerza|aucune force|cap força"),
                Q("joints", 1, "While the glue dries, the pieces are held with…|Mientras seca la cola, las piezas se sujetan con…|Pendant que la colle sèche, on tient les pièces avec…|Mentre s'asseca la cola, les peces se subjecten amb…", "clamps|sargentos o prensas|des serre-joints|serjants o premses", "Pressure keeps the surfaces in close contact so the glue holds.|La presión mantiene las superficies bien juntas para que la cola agarre.|La pression garde les surfaces bien en contact pour que la colle tienne.|La pressió manté les superfícies ben juntes perquè la cola agafi.", "nothing|nada|rien|res", "a magnet|un imán|un aimant|un imant", "hair clips|pinzas del pelo|des pinces à cheveux|pinces dels cabells"),
                Q("joints", 2, "White wood glue (PVA) hardens because…|La cola blanca de carpintero (PVA) endurece porque…|La colle blanche à bois (PVA) durcit parce que…|La cola blanca de fuster (PVA) s'endureix perquè…", "its water evaporates or goes into the wood|su agua se evapora o la absorbe la madera|son eau s'évapore ou part dans le bois|la seva aigua s'evapora o l'absorbeix la fusta", "The polymer particles join together as the water leaves.|Las partículas de polímero se unen a medida que se va el agua.|Les particules de polymère se soudent à mesure que l'eau s'en va.|Les partícules de polímer s'uneixen a mesura que se'n va l'aigua.", "light hardens it|la luz la endurece|la lumière la durcit|la llum l'endureix", "cold hardens it|el frío la endurece|le froid la durcit|el fred l'endureix", "you mix it with sand|se mezcla con arena|on la mélange avec du sable|es barreja amb sorra"),
                Q("joints", 3, "What is a mortise and tenon joint?|¿Qué es una unión de caja y espiga?|Qu'est-ce qu'un assemblage à tenon et mortaise ?|Què és una unió de metxa i encaix?", "A tongue of one piece that fits a hole in the other|Un saliente de una pieza que encaja en un hueco de la otra|Une languette d'une pièce qui entre dans un trou de l'autre|Un sortint d'una peça que encaixa en un forat de l'altra", "The shapes lock the pieces and the glue has a big surface to hold.|Las formas bloquean las piezas y la cola tiene mucha superficie para agarrar.|Les formes bloquent les pièces et la colle a une grande surface où tenir.|Les formes bloquen les peces i la cola té molta superfície per agafar.", "Two pieces glued edge to edge only|Dos piezas pegadas de canto sin más|Deux pièces simplement collées par la tranche|Dues peces enganxades de cantell sense res més", "Two crossed nails|Dos clavos cruzados|Deux clous croisés|Dos claus creuats", "Tape|Cinta adhesiva|Du ruban adhésif|Cinta adhesiva"),
                Q("finish", 1, "When sanding, you start with…|Al lijar se empieza con…|Pour poncer, on commence avec…|Per polir es comença amb…", "coarse grit (low number) and end with fine grit|grano grueso (número bajo) y se termina con grano fino|un grain gros (petit numéro) et on finit avec un grain fin|gra gruixut (número baix) i s'acaba amb gra fi", "Coarse grit removes material fast; finer grits erase the scratches of the previous one.|El grano grueso quita material rápido; los más finos borran las rayas del anterior.|Le gros grain enlève vite la matière ; les plus fins effacent les rayures du précédent.|El gra gruixut treu material ràpid; els més fins esborren les ratlles de l'anterior.", "fine grit, then coarse|grano fino y luego grueso|un grain fin, puis gros|gra fi i després gruixut", "always the same grit|siempre el mismo grano|toujours le même grain|sempre el mateix gra", "coarse grit at the end|grano grueso al final|un gros grain à la fin|gra gruixut al final"),
                Q("finish", 2, "Fine sawdust from sanding can harm…|El polvo fino de lijar madera puede dañar…|La poussière fine de ponçage peut abîmer…|La pols fina de polir fusta pot fer mal…", "the lungs: wear a dust mask|los pulmones: hay que llevar mascarilla|les poumons : il faut un masque|als pulmons: cal portar mascareta", "Tiny particles reach deep into the airways.|Las partículas muy pequeñas llegan muy dentro de las vías respiratorias.|Les très petites particules vont loin dans les voies respiratoires.|Les partícules molt petites arriben molt endins de les vies respiratòries.", "the nails|las uñas|les ongles|les ungles", "the hair|el pelo|les cheveux|els cabells", "nothing|nada|rien|res"),
                Q("finish", 3, "Varnish or oil mainly protect wood from…|El barniz o el aceite protegen la madera sobre todo de…|Le vernis ou l'huile protègent le bois surtout de…|El vernís o l'oli protegeixen la fusta sobretot de…", "moisture and wear|la humedad y el desgaste|l'humidité et l'usure|la humitat i el desgast", "They close the pores, so the wood takes in less water and stains less.|Cierran los poros, así que la madera absorbe menos agua y se mancha menos.|Ils ferment les pores : le bois absorbe moins d'eau et se tache moins.|Tanquen els porus, de manera que la fusta absorbeix menys aigua i es taca menys.", "gravity|la gravedad|la gravité|la gravetat", "sound|el sonido|le son|el so", "moonlight|la luz de la luna|le clair de lune|la llum de la lluna"),
            ]),
